import test from 'node:test';
import assert from 'node:assert/strict';
import { exportCsv } from '../src/export.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('exportCsv returns header and newline for empty list', () => {
  const csv = exportCsv([]);
  assert.equal(csv, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due\n');
});

test('exportCsv with single invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const csv = exportCsv([issued]);

  const lines = csv.split('\n');
  assert.equal(lines.length, 3); // header, invoice, empty line at end
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.match(lines[1], /INV-2026-0001,Blue Fern Bakery,2026-10-07,2026-11-06,issued,85.00,0.00,17.85,102.85,102.85/);
});

test('exportCsv skips null invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const csv = exportCsv([null, issued, undefined]);

  const lines = csv.split('\n');
  assert.equal(lines.length, 3); // header, invoice, empty line
});

test('exportCsv with multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-02',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const csv = exportCsv([issued1, issued2]);

  const lines = csv.split('\n');
  assert.equal(lines.length, 4); // header, 2 invoices, empty line
  assert.match(lines[1], /INV-2026-0001/);
  assert.match(lines[2], /INV-2026-0002/);
});

test('exportCsv with draft invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const csv = exportCsv([invoice]);

  const lines = csv.split('\n');
  assert.equal(lines.length, 3); // header, draft invoice, empty line
  assert.match(lines[1], /,Blue Fern Bakery,2026-10-07,,draft,/);
});

test('exportCsv formats euros with 2 decimals', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-002',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 8500, vatRate: 21 }],
  };

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');

  assert.match(lines[1], /85\.00,0\.00,17\.85,102\.85,102\.85/);
});

test('exportCsv with discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const csv = exportCsv([issued]);

  const lines = csv.split('\n');
  // 17000 - 1700 + 3213 = 18513
  assert.match(lines[1], /170\.00,17\.00,32\.13,185\.13,185\.13/);
});

test('exportCsv with partially paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const partial = recordPayment(issued, { amount: 5000, date: '2026-10-05' }).value;

  const csv = exportCsv([partial]);

  const lines = csv.split('\n');
  // C-001 gold tier: 9771 total, 5000 paid, 4771 due
  assert.match(lines[1], /partially_paid,85\.00,4\.25,16\.96,97\.71,47\.71/);
});

test('exportCsv with paid invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const paid = recordPayment(issued, { amount: 9771, date: '2026-10-05' }).value;

  const csv = exportCsv([paid]);

  const lines = csv.split('\n');
  // Due should be 0 for paid invoice
  assert.match(lines[1], /paid,85\.00,4\.25,16\.96,97\.71,0\.00/);
});

test('exportCsv escapes customer name with comma', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-006', // Marlow "The Print Shop"
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
  };

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');

  assert.match(lines[1], /"Marlow.*Print Shop"/);
});

test('exportCsv escapes customer name with quote', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-006', // Marlow "The Print Shop"
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
  };

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');

  // Should have double quotes escaped
  assert.match(lines[1], /"Marlow ""The Print Shop"""/);
});

test('exportCsv ending with newline', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const csv = exportCsv([issued]);

  assert.ok(csv.endsWith('\n'));
});

test('exportCsv with zero discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const csv = exportCsv([issued]);

  const lines = csv.split('\n');
  assert.match(lines[1], /0\.00.*0\.00/);
});

test('exportCsv with VAT-exempt item', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const csv = exportCsv([issued]);

  const lines = csv.split('\n');
  // 60000 subtotal, 0 discount, 0 VAT, 60000 total
  assert.match(lines[1], /600\.00,0\.00,0\.00,600\.00/);
});

test('exportCsv with tier discount', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const csv = exportCsv([issued]);

  const lines = csv.split('\n');
  // C-001 gold tier: 17000 - 850 + 3392 = 19542
  assert.match(lines[1], /170\.00,8\.50,33\.92,195\.42,195\.42/);
});

test('exportCsv with large amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 5 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const csv = exportCsv([issued]);

  const lines = csv.split('\n');
  // 1225000 + 257250 = 1482250
  assert.match(lines[1], /12250\.00,0\.00,2572\.50,14822\.50/);
});

test('exportCsv with small amounts', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-002',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 1, vatRate: 0 }],
  };

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');

  assert.match(lines[1], /0\.01,0\.00,0\.00,0\.01/);
});

test('exportCsv multiple invoices in order', () => {
  const invoices = [];
  const numbers = [];

  for (let i = 1; i <= 3; i++) {
    const inv = createInvoice({
      customerId: 'C-002',
      issueDate: `2026-10-0${i}`,
      lines: [{ sku: 'DES-HOUR', qty: i }],
    }).value;

    const issued = issueInvoice(inv, numbers).value;
    numbers.push(issued.number);
    invoices.push(issued);
  }

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');

  // Should be in the order given
  assert.match(lines[1], /INV-2026-0001/);
  assert.match(lines[2], /INV-2026-0002/);
  assert.match(lines[3], /INV-2026-0003/);
});

test('exportCsv header line format', () => {
  const csv = exportCsv([]);
  const header = csv.split('\n')[0];

  assert.equal(header, 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv handles customer not found', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-999', // non-existent
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
  };

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');

  // Customer name should be empty string
  assert.match(lines[1], /INV-2026-0001,,2026-10-07/);
});

test('exportCsv with complex discount scenario', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2, discountPercent: 10 },
      { sku: 'PRINT-A4', qty: 50 },
    ],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const csv = exportCsv([issued]);

  const lines = csv.split('\n');
  // DES-HOUR: 17000 - 1700 + 3213 = 18513
  // PRINT-A4: 1850 + 166 = 2016
  // Total: 20529
  assert.match(lines[1], /18\.50,17\.00,32\.13,205\.29/);
});

test('exportCsv with invoice missing number', () => {
  const invoice = {
    customerId: 'C-002',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'draft',
    lines: [{ qty: 1, unitPrice: 1000, vatRate: 0 }],
  };

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');

  // Number field should be empty
  assert.match(lines[1], /^,Blue Fern Bakery/);
});

test('exportCsv decimal point not comma', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-002',
    issueDate: '2026-10-07',
    dueDate: '2026-11-06',
    status: 'issued',
    lines: [{ qty: 1, unitPrice: 12345, vatRate: 0 }],
  };

  const csv = exportCsv([invoice]);
  const lines = csv.split('\n');

  // Should use dot as decimal separator, not comma
  assert.match(lines[1], /123\.45/);
  assert.notMatch(lines[1], /123,45/);
});

test('exportCsv single currency line in file', () => {
  const csv = exportCsv([]);
  const lines = csv.split('\n');

  // Should have exactly 2 lines: header and empty string after final newline
  assert.equal(lines.length, 2);
  assert.equal(lines[1], '');
});

test('exportCsv does not mutate input', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const invoiceCopy = JSON.parse(JSON.stringify([issued]));

  exportCsv([issued]);

  assert.deepEqual([issued], invoiceCopy);
});

test('exportCsv with voucher', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(invoice, []).value;
  const withVoucher = {
    ...issued,
    voucher: { code: 'DISCOUNT', amount: 1000 },
  };

  const csv = exportCsv([withVoucher]);
  const lines = csv.split('\n');

  // Total with voucher: 20570 - 1000 = 19570
  assert.match(lines[1], /195\.70/);
});

